namespace CodebaseReviewTool.Domain.Entities;

/// <summary>Cached pull request metadata, as the repository host reports it.</summary>
public class PullRequest
{
    /// <summary>
    /// The host's pull request id; not generated by the database. The key is this id together with
    /// <see cref="RepositoryKey"/>, so two configured repositories can never overwrite each other's rows.
    /// </summary>
    public int Id { get; set; }

    public string RepositoryKey { get; set; } = string.Empty;

    public string Title { get; set; } = string.Empty;

    public string Description { get; set; } = string.Empty;

    public string AuthorName { get; set; } = string.Empty;

    public string SourceBranch { get; set; } = string.Empty;

    public string TargetBranch { get; set; } = string.Empty;

    public string SourceCommit { get; set; } = string.Empty;

    /// <summary>The host's status text (e.g. <c>active</c>, <c>completed</c>, <c>abandoned</c>).</summary>
    public string Status { get; set; } = string.Empty;

    /// <summary>True while the host marks the pull request as a draft.</summary>
    public bool IsDraft { get; set; }

    /// <summary>The host's merge status text (e.g. <c>succeeded</c>, <c>conflicts</c>, <c>queued</c>, <c>notSet</c>).</summary>
    public string MergeStatus { get; set; } = string.Empty;

    /// <summary>UTC.</summary>
    public DateTime CreatedAt { get; set; }

    public string Url { get; set; } = string.Empty;

    /// <summary>UTC time the poller last saw this PR.</summary>
    public DateTime LastSeenAt { get; set; }

    public bool IsOpen { get; set; }

    public List<Review> Reviews { get; set; } = [];
}
